import { test, expect } from '@playwright/test';

test.describe('Skip-to-Content Link Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should navigate to main content when skip-to-content link is clicked', async ({ page }) => {
    // Verify skip-to-content link is visible
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    await expect(skipLink).toBeVisible();

    // Verify main content is not visible initially
    const mainContent = page.getByRole('main');
    await expect(mainContent).not.toBeVisible();

    // Click the skip-to-content link
    await skipLink.click();

    // Verify main content is now visible
    await expect(mainContent).toBeVisible();

    // Verify main content contains expected content
    const mainHeading = page.getByRole('heading', { name: /main content/i });
    await expect(mainHeading).toBeVisible();

    const mainParagraph = page.getByText(/welcome to our site/i);
    await expect(mainParagraph).toBeVisible();
  });

  test('should not navigate to main content when skip-to-content link is disabled', async ({ page }) => {
    // Verify skip-to-content link is visible
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    await expect(skipLink).toBeVisible();

    // Verify main content is not visible initially
    const mainContent = page.getByRole('main');
    await expect(mainContent).not.toBeVisible();

    // Verify skip-to-content link is disabled
    await expect(skipLink).toHaveAttribute('aria-disabled', 'true');

    // Verify main content remains hidden
    await expect(mainContent).not.toBeVisible();

    // Verify skip-to-content link is still visible
    await expect(skipLink).toBeVisible();

    // Verify skip-to-content link is still disabled
    await expect(skipLink).toHaveAttribute('aria-disabled', 'true');
  });
});
